t.script:
document.addEventListener('DOMContentLoaded', function () {
    function nowISO() {
        return new Date().toISOString();
    }

    function nowLocalString() {
        return new Date().toLocaleString();
    }

    function reverseGeocode(lat, lon) {
        const url = `https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lon)}`;
        return fetch(url, {headers: {'User-Agent': 'odoo-portal-checkin/1.0'}})
                .then(r => r.ok ? r.json() : Promise.reject('nominatim'))
                .then(j => j.display_name || null)
                .catch(() => null);
    }

    // ---- Check In ----
    document.body.addEventListener('click', function (ev) {
        if (!ev.target.classList) return;
        if (ev.target.classList.contains('o-btn-checkin')) {
            const btn = ev.target;
            btn.disabled = true;
            const row = btn.closest('tr');
            const tField = row.querySelector('.checkin-time');
            const locField = row.querySelector('.checkin-loc');
            const partnerId = row.dataset.partnerId;
            const routeId = row.dataset.recId;

            if (!navigator.geolocation) {
                alert('Geolocation not supported');
                btn.disabled = false;
                return;
            }

            navigator.geolocation.getCurrentPosition(async function (pos) {
                const lat = pos.coords.latitude, lon = pos.coords.longitude;
                tField.value = nowLocalString();
                row.dataset.lat_in = lat;
                row.dataset.lon_in = lon;
                row.dataset.checkin_time_iso = nowISO();
                const display = await reverseGeocode(lat, lon);
                locField.value = display || `${lat.toFixed(6)}, ${lon.toFixed(6)}`;


                // 🔴 Auto-post IN record
                const payload = {
                    post: true,
                    partner_id: partnerId,
                    route_plan_id: routeId,
                    latitude_in: lat,
                    longitude_in: lon,
                    check_in_time: row.dataset.checkin_time_iso,
                    check_in_loc: locField.value
                };
                const csrfToken = document.getElementById('csrf_token').value;
                fetch('/create/field/force/rec', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json', 'X-CSRFToken': csrfToken},
                    credentials: 'same-origin',
                    body: JSON.stringify(payload),
                })
                        .then(r => r.json())
                        .then(data => {
                            if (data && data.success) {
                                row.dataset.fieldForceId = data.id; // save created record id
                                console.log('✅ Check-in successfully saved (ID:', data.id, ')');
                            } else {
                                alert('⚠️ Record already exists or failed to save. Please check and try again.');
                            }
                        })
                        .catch(err => {
                            console.error('❌ Network or server error during check-in:', err);
                        });

                btn.disabled = false;
            }, function (err) {
                alert('Unable to get location: ' + (err.message || err.code));
                btn.disabled = false;
            }, {enableHighAccuracy: true, timeout: 30000, maximumAge: 0});
        }
    });


    // ---- Check Out ----
    // inside DOMContentLoaded: replace checkout handler with this
    document.body.addEventListener('click', function (ev) {
        if (!ev.target.classList) return;
        if (ev.target.classList.contains('o-btn-checkout')) {
            const btn = ev.target;
            btn.disabled = true;
            const row = btn.closest('tr');
            const tField = row.querySelector('.checkout-time');
            const locField = row.querySelector('.checkout-loc');
            const totalField = row.querySelector('.total-time');
            const routeId = row.dataset.recId || '';
            const fieldForceId = row.dataset.fieldForceId || '';
            const partnerId = row.dataset.partnerId || '';

            if (!navigator.geolocation) {
                alert('Geolocation not supported');
                btn.disabled = false;
                return;
            }

            navigator.geolocation.getCurrentPosition(async function (pos) {
                const lat = pos.coords.latitude, lon = pos.coords.longitude;
                const now = new Date();
                tField.value = now.toLocaleString();
                row.dataset.lat_out = lat;
                row.dataset.lon_out = lon;
                row.dataset.checkout_time_iso = now.toISOString();

                const display = await reverseGeocode(lat, lon);
                locField.value = display || `${lat.toFixed(6)}, ${lon.toFixed(6)}`;

                // Build payload: include specific field_force_id if we have it
                const payload = {
                    record_id: routeId,
                    partner_id: partnerId,
                    latitude_out: lat,
                    longitude_out: lon,
                    check_out_time: row.dataset.checkout_time_iso,
                    check_out_loc: locField.value
                };
                if (fieldForceId) payload.field_force_id = fieldForceId;

                const csrfToken = document.getElementById('csrf_token').value;
                fetch('/update/field/force/rec', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'X-CSRFToken': csrfToken,
                    },
                    credentials: 'same-origin',
                    body: JSON.stringify(payload),
                })
                        .then(r => r.json())
                        .then(j => {
                            if (j.success) {
                                console.log('Checkout complete for route:', j.route_id, 'ff:', j.field_force_id);
                                // update UI with server-provided check_out data if returned:
                                if (j.check_out && j.check_out.time) row.querySelector('.checkout-time').value = j.check_out.time;
                                if (j.check_out && j.check_out.address) row.querySelector('.checkout-loc').value = j.check_out.address;
                                if (j.total_hours !== undefined && j.total_hours !== null) {
                                    row.querySelector('.total-time').value = (j.total_hours ? j.total_hours + 'h' : '');
                                }
                                // disable buttons (optional)
                                row.querySelectorAll('.o-btn-checkin, .o-btn-checkout').forEach(b => b.disabled = true);
                                // ✅ Add this line here
                                setTimeout(() => {
                                    location.reload();
                                }, 35000);
                            } else {
                                alert('Error updating checkout: ' + (j.error || 'server error'));
                            }
                        })
                        .catch(err => {
                            console.error('Checkout error', err);
                            alert('Network/server error saving checkout');
                        })
                        .finally(() => {
                            btn.disabled = false;
                        });
            }, function (err) {
                alert('Unable to get location: ' + (err.message || err.code));
                btn.disabled = false;
            }, {enableHighAccuracy: true, timeout: 10000});
        }
    });


}); // DOMContentLoaded
